SELECT CASE WHEN p.cost >= 690 THEN 'high' WHEN p.cost >= 200 THEN 'mid' ELSE 'low' END AS cost_bucket, p.supplier_id, AVG(i.quantity) AS avg_quantity FROM inventory i JOIN stores s ON i.store_id = s.id JOIN products p ON p.id = i.product_id WHERE s.store_name IS NOT NULL GROUP BY CASE WHEN p.cost >= 690 THEN 'high' WHEN p.cost >= 200 THEN 'mid' ELSE 'low' END, p.supplier_id HAVING avg_quantity > 190
